const updateSavedView = `-- name: UpdateSavedView :one
UPDATE saved_views
SET name               = $1,
    description        = $2,
    query              = $3,
    visibility         = $4,
    visibility_team_id = $5
WHERE id = $6 AND org_id = $7 AND deleted_at IS NULL
RETURNING id, org_id, owner_id, name, description, query, visibility, visibility_team_id, created_at, updated_at, deleted_at, space_id, position
`

type UpdateSavedViewParams struct {
	Name             string      `json:"name"`
	Description      string      `json:"description"`
	Query            []byte      `json:"query"`
	Visibility       string      `json:"visibility"`
	VisibilityTeamID pgtype.UUID `json:"visibility_team_id"`
	ID               uuid.UUID   `json:"id"`
	OrgID            uuid.UUID   `json:"org_id"`
}

// The whole mutable surface in one statement. There is no partial-PATCH
// pointer here on purpose: a single nullable pointer for visibility_team_id
// would collapse "absent" and "null" into "clear it", which is exactly the
// defect that silently wiped every item's due_at. The handler reads the row,
// applies only the fields the request set, and writes the whole result back.
func (q *Queries) UpdateSavedView(ctx context.Context, arg UpdateSavedViewParams) (SavedView, error) {
	row := q.db.QueryRow(ctx, updateSavedView,
		arg.Name,
		arg.Description,
		arg.Query,
		arg.Visibility,
		arg.VisibilityTeamID,
		arg.ID,
		arg.OrgID,
	)
	var i SavedView
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.OwnerID,
		&i.Name,
		&i.Description,
		&i.Query,
		&i.Visibility,
		&i.VisibilityTeamID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.SpaceID,
		&i.Position,
	)
	return i, err
}
